#include <cinux/addr.hpp>

using namespace cinux::base;

void Example() {
    // 0x1000 起的物理页，往后挪 0x200 字节
    constexpr PhysAddr kPage{0x1000};

    constexpr PhysAddr kInside = kPage.offset(0x200);
    // kInside.raw = 0x1200 · 页内偏移加在地址上，类型仍是物理地址
    static_assert(kInside.raw == 0x1200);

    constexpr PhysAddr kNext = kPage.offset(4096);
    // kNext.raw = 0x2000 · 整页挪过去，落在下一页的页首
    static_assert(kNext.raw == 0x2000);
}
